-- ============================================================================
-- 02 — align the Prisma migration history (generated by scripts/generate-repair-sql.py)
--
-- RUN AFTER 01-schema.sql SUCCEEDED.
--
-- Equivalent to `prisma migrate resolve --applied <name>` for each migration in
-- 01. checksum = SHA-256 of the migration file, exactly what Prisma stores, so
-- `prisma migrate status` / `migrate deploy` accept the history.
--
-- Idempotent: migrations that are already recorded are skipped.
-- ============================================================================


INSERT INTO "_prisma_migrations"
  (id, checksum, finished_at, migration_name, logs, rolled_back_at, started_at, applied_steps_count)
SELECT md5(random()::text || clock_timestamp()::text), '466f29fc545a245342341b134ea443772b5082fb9286767aafbd01fc5a050305', NOW(), '20260902090100_baseline_schema_completion', NULL, NULL, NOW(), 1
WHERE NOT EXISTS (SELECT 1 FROM "_prisma_migrations" WHERE migration_name = '20260902090100_baseline_schema_completion');

